class EmailAgentState { EmailAgentState.fromJson(Map<String,dynamic> json):id='${json['agent']?['id']??''}',status='${json['agent']?['status']??'paused'}',provider='${json['integration']?['provider']??'disconnected'}',connected=json['integration']?['connected']==true,account=json['integration']?['account']?.toString(); final String id,status,provider; final bool connected; final String? account; bool get active=>status=='active'; }
class EmailAgentPolicy { EmailAgentPolicy.fromJson(Map<String,dynamic> j):automaticReplies=j['automatic_replies_enabled']==true,complaintsEscalate=j['complaints_escalate']!=false,sensitiveApproval=j['sensitive_replies_require_approval']!=false,tone='${j['default_tone']??'professional'}'; final bool automaticReplies,complaintsEscalate,sensitiveApproval; final String tone; Map<String,dynamic> toJson()=>{'automatic_replies_enabled':automaticReplies,'complaints_escalate':complaintsEscalate,'sensitive_replies_require_approval':sensitiveApproval,'default_tone':tone}; }
class EmailManualRunResult { EmailManualRunResult.fromJson(Map<String,dynamic> j):noWork=j['no_work']==true,preparedReplyId=j['preparedReplyId']?.toString(),approvalRequested=j['approvalRequested']==true,escalated=j['escalated']==true,skipped=j['skipped']?.toString(); final bool noWork,approvalRequested,escalated; final String? preparedReplyId,skipped; }
